const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Utah geometry
  const utah = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Utah'))
    .geometry();

  // 2. Load ERA5-Land soil moisture data
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY');
  const band = 'volumetric_soil_water_layer_1';

  // 3. August 2020 data
  const aug2020 = era5
    .filterDate('2020-08-01', '2020-09-01')
    .select(band);

  const size2020 = aug2020.size().getInfo();
  console.log('August 2020 images:', size2020);

  if (size2020 === 0) {
    console.log('No data for August 2020');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Long-term August average (1981-2019)
  const longTerm = era5
    .filterDate('1981-08-01', '2019-09-01')
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .select(band);

  const sizeLongTerm = longTerm.size().getInfo();
  console.log('Long-term August images:', sizeLongTerm);

  if (sizeLongTerm === 0) {
    console.log('No long-term data available');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate means
  const mean2020Image = aug2020.mean();
  const meanLongTermImage = longTerm.mean();

  // 6. Reduce over Utah
  const stats2020 = mean2020Image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: utah,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const statsLongTerm = meanLongTermImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: utah,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const val2020 = stats2020[band + '_mean'];
  const count2020 = stats2020[band + '_count'];
  const valLongTerm = statsLongTerm[band + '_mean'];
  const countLongTerm = statsLongTerm[band + '_count'];

  console.log('August 2020 - Mean:', val2020, 'Pixels:', count2020);
  console.log('Long-term August - Mean:', valLongTerm, 'Pixels:', countLongTerm);

  // 7. Validation
  if (count2020 === 0 || countLongTerm === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (val2020 === null || val2020 === undefined || isNaN(val2020) ||
      valLongTerm === null || valLongTerm === undefined || isNaN(valLongTerm)) {
    console.log('Calculation failed - invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (val2020 < 0 || val2020 > 1 || valLongTerm < 0 || valLongTerm > 1) {
    console.log('Invalid soil moisture range');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Final comparison
  const difference = val2020 - valLongTerm;
  const percentChange = ((val2020 - valLongTerm) / valLongTerm * 100).toFixed(2);

  console.log('Difference:', difference.toFixed(4), 'm³/m³');
  console.log('Percent change:', percentChange + '%');

  if (val2020 < valLongTerm) {
    console.log('August 2020 shows DECREASED soil moisture vs long-term');
    console.log('<answer>A</answer>');
  } else {
    console.log('August 2020 shows NO DECREASE in soil moisture vs long-term');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
